import re


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


_NAME_RE = re.compile(r'^[md][0-9]{6}\.bin$')


def _safe_path(p):
    if not isinstance(p, str):
        raise ValueError('path must be string')
    if p == '' or p != p.strip():
