    def test_chunks_output_contract(self):
        payload = {
            "files": [{"path": "a.txt", "hex": "616263"}],
            "max_file_bytes": 16,
            "max_entries": 2,
        }
        contract = {"name": "chunks", "operation": "reshard_chunks", "inputs": ["x"], "output": "y"}
